pair<int, int> farthest(const vector<vector<int>> &g, int start) {
    vector<int> dist(g.size(), -1);
    queue<int> q;
    q.push(start);
    dist[start] = 0;
    int best = start;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        if (dist[u] > dist[best]) best = u;
        for (int v : g[u]) {
            if (dist[v] != -1) continue;
            dist[v] = dist[u] + 1;
            q.push(v);
        }
    }
    return {best, dist[best]};
}

